-- Mondlicht — Hyprland 0.57+ Lua Configuration

local ok, c = pcall(require, "colors")
if not ok or type(c) ~= "table" then
    c = {
        active_a = "rgba(dce4f7e6)",
        active_b = "rgba(b7a6e8b8)",
        inactive = "rgba(2a2f42aa)",
        shadow   = 0xf005060a,
        glow     = "rgba(a9bceb33)",
        accent   = "#a9bceb",
        surface  = "#08090e",
    }
end

-- Host-specific monitors & GPU env (generated by install.sh into ~/.config/hypr/host.lua)
local host_ok = pcall(require, "host")
if not host_ok then
    hl.monitor({
        output   = "",
        mode     = "preferred",
        position = "auto",
        scale    = "auto",
    })
end

-- Programs
local terminal    = "kitty"
local fileManager = "dolphin"
local menu        = "fuzzel"

-- Environment variables
hl.env("SHELL", "/usr/bin/zsh")
hl.env("XCURSOR_THEME", "capitaine-cursors")
hl.env("XCURSOR_SIZE", "24")
hl.env("HYPRCURSOR_SIZE", "24")
hl.env("QT_QPA_PLATFORM", "wayland;xcb")
hl.env("QT_QPA_PLATFORMTHEME", "qt6ct")
hl.env("ELECTRON_OZONE_PLATFORM_HINT", "auto")
hl.env("GDK_BACKEND", "wayland,x11,*")

-- Core look & feel (Mondlicht smoked glass + lunar rim)
hl.config({
    general = {
        gaps_in     = 5,
        gaps_out    = 10,
        border_size = 1,
        col = {
            active_border   = { colors = { c.active_a, c.active_b, c.inactive }, angle = 45 },
            inactive_border = c.inactive,
        },
        resize_on_border = true,
        allow_tearing    = false,
        layout           = "dwindle",
    },

    decoration = {
        rounding         = 6,
        rounding_power   = 2.5,
        active_opacity   = 1.0,
        inactive_opacity = 0.96,

        shadow = {
            enabled        = true,
            range          = 18,
            render_power   = 3,
            color          = c.shadow,
            color_inactive = 0xaa05060a,
            offset         = { 0, 4 },
        },

        glow = {
            enabled        = true,
            range          = 8,
            render_power   = 2,
            color          = c.glow,
            color_inactive = "rgba(00000000)",
        },

        blur = {
            enabled           = true,
            size              = 4,
            passes            = 1,
            new_optimizations = true,
            noise             = 0.0,
            contrast          = 1.0,
            brightness        = 0.80,
            vibrancy          = 0.0,
            vibrancy_darkness = 0.0,
            popups            = false,
        },
    },

    xwayland = {
        force_zero_scaling = true,
    },

    dwindle = {
        preserve_split = true,
    },

    master = {
        new_status = "master",
    },

    misc = {
        force_default_wallpaper = 0,
        disable_hyprland_logo   = true,
        disable_splash_rendering = true,
    },

    layers = {
        allow_new_top_layers_over_existing_fullscreen = true,
    },

    input = {
        kb_layout    = "us",
        follow_mouse = 1,
        sensitivity  = 0,
        touchpad = {
            natural_scroll = true,
            tap_to_click   = true,
        },
    },

    gestures = {
        workspace_swipe_create_new         = true,
        workspace_swipe_invert             = true,
        workspace_swipe_distance           = 260,
        workspace_swipe_cancel_ratio       = 0.28,
        workspace_swipe_min_speed_to_force = 20,
        workspace_swipe_direction_lock     = true,
    },

    animations = {
        enabled = true,
    },
})

-- Persistent user overrides written by Mondlicht Settings
pcall(require, "user-prefs")

-- Lightweight 60fps animations
hl.curve("obsidianOut", { type = "bezier", points = { {0.16, 1}, {0.30, 1} } })
hl.curve("obsidianQuick", { type = "bezier", points = { {0.20, 0}, {0.10, 1} } })

hl.animation({ leaf = "global",     enabled = true, speed = 5,   bezier = "obsidianOut" })
hl.animation({ leaf = "windows",    enabled = true, speed = 4,   bezier = "obsidianOut", style = "popin 90%" })
hl.animation({ leaf = "windowsOut", enabled = true, speed = 3,   bezier = "obsidianQuick", style = "popin 92%" })
hl.animation({ leaf = "fade",       enabled = true, speed = 3.5, bezier = "obsidianOut" })
hl.animation({ leaf = "layers",     enabled = true, speed = 3.5, bezier = "obsidianOut", style = "fade" })
hl.animation({ leaf = "workspaces", enabled = true, speed = 3.5, bezier = "obsidianOut", style = "slide" })

-- Touchpad gestures (GNOME 45+ 3-finger horizontal workspace + 2-stage vertical Overview/App Grid)
hl.gesture({
    fingers   = 3,
    direction = "horizontal",
    action    = "workspace",
})
hl.gesture({
    fingers   = 3,
    direction = "up",
    action    = function()
        hl.exec_cmd("qs -c mondlicht ipc call shell gestureUp")
    end,
})
hl.gesture({
    fingers   = 3,
    direction = "down",
    action    = function()
        hl.exec_cmd("qs -c mondlicht ipc call shell gestureDown")
    end,
})

-- Layer rules: frosted blur on fuzzel launcher; Quickshell owns its own glass/animations cleanly
hl.layer_rule({
    name         = "obsidian-blur-launcher",
    match        = { namespace = "^(launcher)$" },
    blur         = true,
    ignore_alpha = 0.50,
})
for _, ns in ipairs({
    "obsidian-shell",
    "obsidian-popover",
    "obsidian-dock",
    "obsidian-overview",
}) do
    hl.layer_rule({
        name    = "obsidian-noanim-" .. ns,
        match   = { namespace = "^(" .. ns .. ")$" },
        no_anim = true,
    })
end

-- Window rules
hl.window_rule({
    name           = "suppress-maximize-events",
    match          = { class = ".*" },
    suppress_event = "maximize",
})

hl.window_rule({
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },
    no_focus = true,
})

local floatingClasses = {
    "^(org\\.pulseaudio\\.pavucontrol|pavucontrol)$",
    "^(blueman-manager)$",
    "^(nm-connection-editor)$",
    "^(com\\.gabm\\.satty|satty)$",
    "^(org\\.kde\\.polkit-kde-authentication-agent-1)$",
}
for idx, cls in ipairs(floatingClasses) do
    hl.window_rule({
        name   = "float-util-" .. idx,
        match  = { class = cls },
        float  = true,
        center = true,
    })
end

hl.window_rule({
    name  = "pip-float",
    match = { title = "^(Picture-in-Picture)$" },
    float = true,
    pin   = true,
})

hl.window_rule({
    name   = "mondlicht-settings-float",
    match  = { title = "^(Mondlicht Settings)$" },
    float  = true,
    center = true,
})

-- Autostart (session daemons managed by systemd --user under graphical-session.target)
hl.on("hyprland.start", function()
    hl.exec_cmd("sh -c 'awww query >/dev/null 2>&1 || awww-daemon'")
    hl.exec_cmd("sh -c 'sleep 0.4 && awww restore >/dev/null 2>&1 || true'")
end)

-- Keybindings (macOS-friendly: SUPER = Cmd)
local mainMod = "SUPER"

hl.bind(mainMod .. " + Space",         hl.dsp.exec_cmd("qs -c mondlicht ipc call shell toggleLauncher"), { dont_inhibit = true })
hl.bind(mainMod .. " + R",             hl.dsp.exec_cmd(menu))
hl.bind(mainMod .. " + Q",             hl.dsp.window.close())
hl.bind(mainMod .. " + Return",        hl.dsp.exec_cmd(terminal))
hl.bind(mainMod .. " + E",             hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + Tab",           hl.dsp.exec_cmd("qs -c mondlicht ipc call shell cycleOverview 1"), { dont_inhibit = true })
hl.bind("ALT + Tab",                   hl.dsp.exec_cmd("qs -c mondlicht ipc call shell cycleOverview 1"), { dont_inhibit = true })
hl.bind(mainMod .. " + SHIFT + Tab",   hl.dsp.exec_cmd("qs -c mondlicht ipc call shell cycleOverview -1"), { dont_inhibit = true })
hl.bind("ALT + SHIFT + Tab",           hl.dsp.exec_cmd("qs -c mondlicht ipc call shell cycleOverview -1"), { dont_inhibit = true })
hl.bind("CTRL + left",                 hl.dsp.focus({ workspace = "e-1" }))
hl.bind("CTRL + right",                hl.dsp.focus({ workspace = "e+1" }))
hl.bind("CTRL + SHIFT + left",         hl.dsp.window.move({ workspace = "r-1" }))
hl.bind("CTRL + SHIFT + right",        hl.dsp.window.move({ workspace = "r+1" }))
hl.bind(mainMod .. " + SHIFT + Page_Up",   hl.dsp.window.move({ workspace = "r-1" }))
hl.bind(mainMod .. " + SHIFT + Page_Down", hl.dsp.window.move({ workspace = "r+1" }))
hl.bind(mainMod .. " + A",             hl.dsp.exec_cmd("qs -c mondlicht ipc call shell toggleQuickSettings"))
hl.bind(mainMod .. " + comma",         hl.dsp.exec_cmd("~/.local/bin/mondlicht-settings"))
hl.bind(mainMod .. " + slash",         hl.dsp.exec_cmd("qs -c mondlicht ipc call shell toggleGuide"), { dont_inhibit = true })
hl.bind(mainMod .. " + T",             hl.dsp.exec_cmd("qs -c mondlicht ipc call shell toggleClock"))
hl.bind(mainMod .. " + N",             hl.dsp.exec_cmd("qs -c mondlicht ipc call shell toggleNotifications"))
hl.bind(mainMod .. " + SHIFT + W",     hl.dsp.exec_cmd("qs -c mondlicht ipc call shell toggleWallpaper"))
hl.bind(mainMod .. " + SHIFT + V",     hl.dsp.exec_cmd("~/.local/bin/clip-pick"))
hl.bind(mainMod .. " + F",             hl.dsp.window.fullscreen())
hl.bind(mainMod .. " + SHIFT + F",     hl.dsp.window.fullscreen({ mode = "maximized" }))
hl.bind(mainMod .. " + SHIFT + Space", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + B",             hl.dsp.exec_cmd("~/.local/bin/night-light"))
hl.bind(mainMod .. " + CTRL + Q",      hl.dsp.exec_cmd("hyprlock"))
hl.bind(mainMod .. " + L",             hl.dsp.exec_cmd("hyprlock"))
hl.bind(mainMod .. " + Escape",        hl.dsp.exec_cmd("qs -c mondlicht ipc call shell togglePower"))
hl.bind(mainMod .. " + SHIFT + 4",     hl.dsp.exec_cmd("~/.local/bin/screenshot region"))
hl.bind(mainMod .. " + SHIFT + 3",     hl.dsp.exec_cmd("~/.local/bin/screenshot full"))
hl.bind(mainMod .. " + SHIFT + 5",     hl.dsp.exec_cmd("~/.local/bin/screen-record region"))
hl.bind(mainMod .. " + SHIFT + 6",     hl.dsp.exec_cmd("~/.local/bin/screen-record full"))
hl.bind("Print",                       hl.dsp.exec_cmd("~/.local/bin/screenshot region"))
hl.bind("SHIFT + Print",               hl.dsp.exec_cmd("~/.local/bin/screenshot full"))

hl.bind(mainMod .. " + P", hl.dsp.window.pseudo())
hl.bind(mainMod .. " + J", hl.dsp.layout("togglesplit"))
hl.bind(mainMod .. " + M", hl.dsp.exec_cmd("uwsm stop || hyprctl dispatch 'hl.dsp.exit()'"))

-- Focus
hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "down" }))

-- Move window (tile swap / directional move)
hl.bind(mainMod .. " + SHIFT + left",  hl.dsp.window.move({ direction = "left" }))
hl.bind(mainMod .. " + SHIFT + right", hl.dsp.window.move({ direction = "right" }))
hl.bind(mainMod .. " + SHIFT + up",    hl.dsp.window.move({ direction = "up" }))
hl.bind(mainMod .. " + SHIFT + down",  hl.dsp.window.move({ direction = "down" }))

-- Resize window
hl.bind(mainMod .. " + ALT + left",  hl.dsp.window.resize({ x = -40, y = 0,   relative = true }), { repeating = true })
hl.bind(mainMod .. " + ALT + right", hl.dsp.window.resize({ x = 40,  y = 0,   relative = true }), { repeating = true })
hl.bind(mainMod .. " + ALT + up",    hl.dsp.window.resize({ x = 0,   y = -40, relative = true }), { repeating = true })
hl.bind(mainMod .. " + ALT + down",  hl.dsp.window.resize({ x = 0,   y = 40,  relative = true }), { repeating = true })

-- Workspaces 1..10
for i = 1, 10 do
    local key = i % 10
    hl.bind(mainMod .. " + " .. key,         hl.dsp.focus({ workspace = i }))
    hl.bind(mainMod .. " + SHIFT + " .. key, hl.dsp.window.move({ workspace = i }))
end

-- Scratchpad (Cmd+S shows/hides Scratchpad; Cmd+Shift+S stashes window OR pulls it back out)
hl.bind(mainMod .. " + S",         hl.dsp.workspace.toggle_special("magic"))
hl.bind(mainMod .. " + SHIFT + S", function()
    local w = hl.get_active_window()
    if w and w.workspace and w.workspace.special then
        local ws = hl.get_active_workspace()
        hl.dispatch(hl.dsp.window.move({ workspace = (ws and ws.id) or 1 }))
    else
        hl.dispatch(hl.dsp.window.move({ workspace = "special:magic" }))
    end
end)

-- Mouse workspace & drag/resize
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))
hl.bind(mainMod .. " + mouse:272",  hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273",  hl.dsp.window.resize(), { mouse = true })

-- Multimedia & brightness (chained with native Quickshell OSD pill)
hl.bind("XF86AudioRaiseVolume",  hl.dsp.exec_cmd("sh -c 'wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+ && qs -c mondlicht ipc call shell showOsd volume'"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume",  hl.dsp.exec_cmd("sh -c 'wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%- && qs -c mondlicht ipc call shell showOsd volume'"),      { locked = true, repeating = true })
hl.bind("XF86AudioMute",         hl.dsp.exec_cmd("sh -c 'wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle && qs -c mondlicht ipc call shell showOsd volume'"),     { locked = true, repeating = true })
hl.bind("XF86AudioMicMute",      hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),   { locked = true, repeating = true })
hl.bind("XF86MonBrightnessUp",   hl.dsp.exec_cmd("sh -c 'command -v brightnessctl >/dev/null && brightnessctl -e4 -n2 set 5%+ && qs -c mondlicht ipc call shell showOsd brightness || true'"),   { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("sh -c 'command -v brightnessctl >/dev/null && brightnessctl -e4 -n2 set 5%- && qs -c mondlicht ipc call shell showOsd brightness || true'"),   { locked = true, repeating = true })
hl.bind("XF86AudioNext",         hl.dsp.exec_cmd("playerctl next"),       { locked = true })
hl.bind("XF86AudioPause",        hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay",         hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev",         hl.dsp.exec_cmd("playerctl previous"),   { locked = true })
